<?php declare(strict_types=1);require_once __DIR__.'/../../bootstrap/app.php';use App\Services\Auth;use App\Services\DriverService;use App\Support\Url;Auth::requirePermission('DRIVER_REVIEW_QUEUE_VIEW');$rows=DriverService::reviewQueue();$pageTitle='Driver Verification Queue';require BASE_PATH.'/app/Views/layout/header.php';?><div class="page-head"><div><h1>Driver verification queue</h1><p>Carrier-approved Drivers awaiting McCollins Operations verification.</p></div><span class="badge"><?=h(count($rows))?> pending</span></div><div class="card table-wrap"><table><thead><tr><th>Driver</th><th>Carrier</th><th>Identity</th><th>Licence</th><th>Medical</th><th>Password setup</th><th></th></tr></thead><tbody><?php foreach($rows as$r):?><tr><td><?=h($r['display_name'])?></td><td><?=h($r['carrier_company_name']?:$r['carrier_user_name'])?></td><td><?=h($r['identity_type'].' · '.$r['identity_number'])?></td><td><?=h($r['licence_number'].' · '.$r['licence_expiry'])?></td><td><?=h($r['medical_result'].' · '.$r['medical_expiry'])?></td><td><?=h($r['setup_used_at']?'Completed':'Pending')?></td><td><a href="<?=h(Url::to('operations/driver-review.php?id='.$r['verification_case_id']))?>">Review</a></td></tr><?php endforeach;if(!$rows):?><tr><td colspan="7" class="muted">No pending Driver verifications.</td></tr><?php endif;?></tbody></table></div><?php require BASE_PATH.'/app/Views/layout/footer.php';
